"use client";

import { useEffect } from "react";

// ── Scroll lock ──────────────────────────────────────────────────────────
// Lifted out of Modal so drawers, sheets and any future overlay share one
// counter: nested or back-to-back overlays must not unlock early. The
// scrollbar's width is paid back as body padding, so the page never shifts
// sideways when it disappears.

let lockCount = 0;
let savedOverflow = "";
let savedPadding = "";

export function lockScroll() {
  if (lockCount++ > 0) return;
  const gap = window.innerWidth - document.documentElement.clientWidth;
  savedOverflow = document.body.style.overflow;
  savedPadding = document.body.style.paddingRight;
  document.body.style.overflow = "hidden";
  if (gap > 0) document.body.style.paddingRight = `${gap}px`;
}

export function unlockScroll() {
  if (--lockCount > 0) return;
  lockCount = 0;
  document.body.style.overflow = savedOverflow;
  document.body.style.paddingRight = savedPadding;
}

/**
 * Locks page scroll while `active` (default: for the whole mount). Modal
 * holds it through its exit animation, so the scrollbar does not come back
 * under a panel that is still fading.
 */
export function useScrollLock(active = true) {
  useEffect(() => {
    if (!active) return;
    lockScroll();
    return unlockScroll;
  }, [active]);
}

/* Themed scrolling. Three parts, all tokens:

   - thin native scrollbars in a tint of the brand (--scrollbar-width,
     --scrollbar-thumb, --scrollbar-track), never a JS scrollbar;
   - overscroll-behavior: contain, so reaching the end of a list never
     scrolls the page behind it;
   - edge shadows at the start and end (--scroll-edge-top, --scroll-edge-bottom),
     shown by useScrollEdges' data-scrolled and data-more attributes. */

.themed {
  overscroll-behavior: contain;
  scrollbar-width: var(--scrollbar-width);
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}

/* ── ScrollArea: a clipped frame round a scrolling viewport ────────────
   The edges are pseudo-elements parked just outside the frame, so only
   their shadows fall inside it: the same hairline and soft shade the modal
   header and footer cast, and no box of their own over the content. */

.area {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
  border-radius: inherit;
}

.viewport {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
}

.x .viewport {
  overflow-y: hidden;
}

/* Sized by its content, so the observer sees a wide table grow. */
.x .content {
  width: max-content;
  min-width: 100%;
}

.y .viewport {
  overflow-x: hidden;
}

.area::before,
.area::after {
  content: "";
  position: absolute;
  z-index: 1;
  left: 0;
  right: 0;
  height: 40px;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--dur-slow) var(--ease);
}

.area::before {
  bottom: 100%;
  box-shadow: var(--scroll-edge-top);
}

.area::after {
  top: 100%;
  box-shadow: var(--scroll-edge-bottom);
}

/* Horizontal: the same edges, turned to the left and right. */
.x::before,
.x::after {
  top: 0;
  bottom: 0;
  width: 40px;
  height: auto;
}

.x::before {
  left: auto;
  right: 100%;
  box-shadow: var(--scroll-edge-left);
}

.x::after {
  left: 100%;
  right: auto;
  box-shadow: var(--scroll-edge-right);
}

.area[data-scrolled]::before,
.area[data-more]::after {
  opacity: 1;
}

.viewport:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px var(--focus-color);
}

"use client";

import { useRef, type CSSProperties, type HTMLAttributes, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import styles from "./Scroll.module.css";
import { useScrollEdges } from "./useScrollEdges";

/** The scrollbar and overscroll half of the pattern, for a scroller you already have. */
export const themedScrollClass = styles.themed;

export type ScrollAreaProps = Omit<HTMLAttributes<HTMLDivElement>, "children"> & {
  /** Caps the viewport; the content scrolls past it. Any CSS length. */
  maxHeight?: CSSProperties["maxHeight"];
  /** "y" (default) for lists and long copy, "x" for wide tables. */
  axis?: "y" | "x";
  /**
   * A name for the scrolling region. When set, the viewport joins the tab
   * order (a keyboard user can scroll it) and is announced as a region.
   */
  label?: string;
  children?: ReactNode;
};

/**
 * Any scroll container, done the modal's way: thin brand-tinted scrollbars,
 * contained overscroll, and edge shadows that appear only once there is
 * something past the edge. No scroll listener reaches React state.
 */
export function ScrollArea({ maxHeight, axis = "y", label, className, style, children, ...rest }: ScrollAreaProps) {
  const areaRef = useRef<HTMLDivElement>(null);
  const viewportRef = useRef<HTMLDivElement>(null);
  useScrollEdges(viewportRef, { target: areaRef, axis });

  return (
    <div data-slot="scroll-area" ref={areaRef} className={cx(styles.area, styles[axis], className)} style={style} {...rest}>
      <div
        ref={viewportRef}
        className={cx(styles.viewport, styles.themed)}
        style={{ maxHeight }}
        tabIndex={label ? 0 : undefined}
        role={label ? "region" : undefined}
        aria-label={label}
      >
        {/* The observed box: it grows with the content while the viewport stays clamped. */}
        <div className={styles.content}>{children}</div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

export type ScrollEdgesOptions = {
  /**
   * The element that gets the attributes. Defaults to the scroller itself.
   * Modal puts them on the panel, so its header and footer (siblings of the
   * scrolling body) can draw the edge shadows.
   */
  target?: RefObject<HTMLElement | null>;
  /** Which way the content scrolls. "x" for wide tables. */
  axis?: "y" | "x";
  /** Off until the scroller exists (a portal before hydration, a body-less modal). */
  enabled?: boolean;
  /**
   * Called whenever the reader reaches the far edge (data-more clears), and
   * straight away when the content does not overflow at all. Gate an
   * "I agree" on it: the terms have been scrolled to the end.
   */
  onEnd?: () => void;
};

/**
 * Scroll-aware edges, written straight to the DOM so scrolling never
 * re-renders React:
 *
 * - `data-scrolled` while the content has moved off its start edge, so the
 *   leading edge (a header, the top of a list) can draw a hairline and shade;
 * - `data-more` while there is content past the far edge, so the trailing
 *   edge (a footer, the bottom of a list) can say "keep going".
 *
 * A passive scroll listener plus a ResizeObserver on the scroller and its
 * first child, so content that grows (an error appearing, a step changing)
 * updates the edges without a scroll. Pair it with ScrollArea, or style
 * `[data-scrolled]` / `[data-more]` yourself with --scroll-edge-top and
 * --scroll-edge-bottom.
 */
export function useScrollEdges(ref: RefObject<HTMLElement | null>, options: ScrollEdgesOptions = {}) {
  const { target, axis = "y", enabled = true, onEnd } = options;
  const onEndRef = useRef(onEnd);
  useEffect(() => {
    onEndRef.current = onEnd;
  }, [onEnd]);

  useEffect(() => {
    const scroller = ref.current;
    if (!enabled || !scroller) return;
    const el = target?.current ?? scroller;
    const content = scroller.firstElementChild;

    const update = () => {
      const pos = axis === "y" ? scroller.scrollTop : Math.abs(scroller.scrollLeft);
      const max = axis === "y"
        ? scroller.scrollHeight - scroller.clientHeight
        : scroller.scrollWidth - scroller.clientWidth;
      el.toggleAttribute("data-scrolled", pos > 1);
      const more = max - pos > 1;
      el.toggleAttribute("data-more", more);
      if (!more) onEndRef.current?.();
    };

    update();
    scroller.addEventListener("scroll", update, { passive: true });
    const ro = new ResizeObserver(update);
    ro.observe(scroller);
    if (content) ro.observe(content);
    return () => {
      scroller.removeEventListener("scroll", update);
      ro.disconnect();
      el.removeAttribute("data-scrolled");
      el.removeAttribute("data-more");
    };
  }, [ref, target, axis, enabled]);
}
